<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole(['counter_staff','handling_staff','supervisor','system_admin']);$pdo=$db->getConnection();$bag=null;$history=[];$msg='';$search=$_GET['baggage_id']??($_GET['baggage_code']??'');if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['baggage_id'],$_POST['status'])){try{$pdo->beginTransaction();$stmt=$pdo->prepare("UPDATE baggage SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?");$stmt->execute([$_POST['status'],$_POST['baggage_id']]);$loc=$_POST['location_id']?:null;$stmt=$pdo->prepare("INSERT INTO tracking_logs (baggage_id,location_id,status,remarks,scanned_by,scan_type,actual_scan_time) VALUES (?,?,?,?,?,'manual',NOW())");$stmt->execute([$_POST['baggage_id'],$loc,$_POST['status'],trim($_POST['remarks']??''),$auth->getUserId()]);$pdo->commit();$msg='Tracking updated successfully';$search=$_POST['baggage_id'];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg='Unable to update tracking';}}if($search!==''){$stmt=$pdo->prepare("SELECT b.*,u.full_name,f.flight_number FROM baggage b JOIN users u ON b.passenger_id=u.id JOIN flights f ON b.flight_id=f.id WHERE b.id=? OR b.baggage_code=?");$stmt->execute([$search,$search]);$bag=$stmt->fetch();if($bag){$stmt=$pdo->prepare("SELECT tl.*,l.location_name,u.full_name staff_name FROM tracking_logs tl LEFT JOIN locations l ON tl.location_id=l.id LEFT JOIN users u ON tl.scanned_by=u.id WHERE tl.baggage_id=? ORDER BY tl.actual_scan_time DESC");$stmt->execute([$bag['id']]);$history=$stmt->fetchAll();}}$locations=$pdo->query("SELECT id,location_name FROM locations WHERE status='active' ORDER BY location_name")->fetchAll();$statuses=['checked_in','security_check','sorting_facility','loaded_to_aircraft','in_transit','unloaded_from_aircraft','at_carousel','claimed','delayed','lost'];
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tracking Update</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><a href="dashboard.php">← Dashboard</a><h2>Tracking Update</h2><?php if($msg):?><div class="alert alert-info"><?=htmlspecialchars($msg)?></div><?php endif;?><form class="row g-2 my-3" method="get"><div class="col-md-9"><input class="form-control" name="baggage_code" placeholder="Baggage code" value="<?=htmlspecialchars(is_string($search)?$search:'')?>"></div><div class="col-md-3"><button class="btn btn-primary w-100">Find</button></div></form><?php if($bag):?><div class="card mb-3"><div class="card-body"><h4><?=htmlspecialchars($bag['baggage_code'])?></h4><p><?=htmlspecialchars($bag['full_name'])?> · <?=htmlspecialchars($bag['flight_number'])?> · Current: <strong><?=htmlspecialchars($bag['status'])?></strong></p><form method="post"><input type="hidden" name="baggage_id" value="<?=intval($bag['id'])?>"><div class="row g-2"><div class="col-md-4"><select class="form-select" name="status" required><?php foreach($statuses as $s):?><option value="<?=$s?>" <?=$s===$bag['status']?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="col-md-4"><select class="form-select" name="location_id"><option value="">No location</option><?php foreach($locations as $l):?><option value="<?=intval($l['id'])?>"><?=htmlspecialchars($l['location_name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><input class="form-control" name="remarks" placeholder="Remarks"></div></div><button class="btn btn-success mt-3">Save update</button></form></div></div><div class="card"><div class="card-header">History</div><ul class="list-group list-group-flush"><?php foreach($history as $h):?><li class="list-group-item"><?=htmlspecialchars($h['status'])?> · <?=htmlspecialchars($h['location_name']??'')?> · <?=htmlspecialchars($h['staff_name']??'')?> · <?=htmlspecialchars($h['actual_scan_time']??'')?></li><?php endforeach;?></ul></div><?php endif;?></div></body></html>